s{\.toString\(16\)\.padStart\(16, "0"\)}:
s{try \{
\s*book = parseBook\(read\(\)\);
\s*\} catch \(error\) \{
\s*switchOff\(error instanceof BookRefused \? error\.message : "could not be read"\);
\s*\}}{book = parseBook(read());}

s{try \{
\s*root = JSON\.parse\((.*?)\);
\s*\} catch \{
\s*throw new BookRefused\("is not valid UTF-8 JSON"\);
\s*\}}{root = JSON.parse($1);}

s{(const switchOff = \(reason: string\): void => \{
\s*book = null;
\s*warn\(`opening book \$\{reason\}; playing on without it`\);
\s*\};)}{$1
  try {
    book = parseBook(read());
  } catch (error) {
    switchOff(error instanceof BookRefused ? error.message : "could not be read");
  }}
